// ============ MOB-6 (Phase 3 WS-D) — generate the typed API client ============
// Reads the OpenAPI 3.1 contract (src/api-contract/openapi-v1.ts) and emits
// the TypeScript client at src/api-client/index.ts. Run:
//     bun run scripts/gen-api-client.ts
// The generated file is committed; re-run whenever the contract changes (the
// contract test fails if the two drift apart).
import * as fs from "fs"
import * as path from "path"
import { OPENAPI_V1_SPEC } from "../src/api-contract/openapi-v1"

type RawParam = { name?: string; in: string; required?: boolean; "$ref"?: string }
type Spec = {
  paths: Record<string, Record<string, {
    operationId: string
    tags?: string[]
    summary?: string
    parameters?: RawParam[]
  }>>
  components?: { parameters?: Record<string, { name: string; in: string; required?: boolean }> }
}

const spec = OPENAPI_V1_SPEC as Spec

/** Resolve $ref'd parameters against #/components/parameters. */
function paramNames(params: RawParam[] | undefined): string[] {
  return (params || []).map((p) => {
    if (p.name) return p.name
    const key = (p["$ref"] || "").split("/").pop() || ""
    return spec.components?.parameters?.[key]?.name || ""
  }).filter(Boolean)
}

function jsDoc(op: { summary?: string }, extra: string[] = []): string {
  const lines = [op.summary || "", ...extra].filter(Boolean)
  if (!lines.length) return ""
  return `  /** ${lines.join(" ")} */\n`
}

const HEADER = [
  "// ============ GENERATED Finix HR public API client (v1) — DO NOT EDIT =======",
  "// Generated by scripts/gen-api-client.ts from src/api-contract/openapi-v1.ts.",
  "// Regenerate with: bun run scripts/gen-api-client.ts",
  "//",
  "// Usage:",
  "//   const api = new FinixApiClient({ baseUrl: \"https://hrm.example.com\" })",
  "//   await api.passwordGrant(\"admin@corp.com\", \"…\", [\"employees:read\"])",
  "//   const directory = await api.listAllEmployees({ updatedSince }) // delta sync",
  "//   const page = await api.listEmployees({ pageSize: 100 })",
  "//   const same = await api.listEmployees({ pageSize: 100, ifNoneMatch: page.etag }) // 304-safe",
  "",
  "export type ApiError = { ok: false; error: string; code: string }",
  "",
  "export type PageResult<T> = {",
  "  ok: true",
  "  data: T[]",
  "  meta: Record<string, unknown> & { nextCursor?: string | null; hasMore?: boolean; total?: number }",
  "  etag: string | null",
  "  notModified: boolean",
  "}",
  "",
  "export type TokenPair = {",
  "  access_token: string",
  "  token_type: \"Bearer\"",
  "  expires_in: number",
  "  refresh_token: string",
  "  scope: string",
  "}",
  "",
  "export class FinixApiClient {",
  "  private accessToken: string | null = null",
  "  private refreshToken: string | null = null",
  "  private apiKey: string | null = null",
  "",
  "  constructor(private opts: {",
  "    baseUrl: string",
  "    /** tenant API key (fk_…) — used when no user token is set */",
  "    apiKey?: string",
  "    fetchImpl?: typeof fetch",
  "  }) {",
  "    this.apiKey = opts.apiKey ?? null",
  "  }",
  "",
  "  /** Set/update the user access token (from passwordGrant/refresh, or your own storage). */",
  "  setAccessToken(token: string | null): void { this.accessToken = token }",
  "  getAccessToken(): string | null { return this.accessToken }",
  "",
  "  /** Password grant — issues and stores an access+refresh pair. */",
  "  async passwordGrant(email: string, password: string, scopes?: string[]): Promise<TokenPair> {",
  "    const body: Record<string, unknown> = { grant_type: \"password\", email, password }",
  "    if (scopes) body.scopes = scopes",
  "    const res = await this.raw(\"POST\", \"/api/v1/auth/token\", body)",
  "    const json = await res.json()",
  "    if (!res.ok || !json?.ok) throw Object.assign(new Error(json?.error || \"token grant failed\"), { code: json?.code, status: res.status })",
  "    this.accessToken = json.data.access_token",
  "    this.refreshToken = json.data.refresh_token",
  "    return json.data as TokenPair",
  "  }",
  "",
  "  /** Refresh grant — rotates the stored refresh token. */",
  "  async refresh(): Promise<TokenPair> {",
  "    if (!this.refreshToken) throw new Error(\"No refresh token stored — call passwordGrant first\")",
  "    const res = await this.raw(\"POST\", \"/api/v1/auth/token\", { grant_type: \"refresh_token\", refresh_token: this.refreshToken })",
  "    const json = await res.json()",
  "    if (!res.ok || !json?.ok) throw Object.assign(new Error(json?.error || \"refresh failed\"), { code: json?.code, status: res.status })",
  "    this.accessToken = json.data.access_token",
  "    this.refreshToken = json.data.refresh_token",
  "    return json.data as TokenPair",
  "  }",
  "",
  "  private async raw(method: \"GET\" | \"POST\" | \"DELETE\", urlPath: string, body?: unknown, headers: Record<string, string> = {}): Promise<Response> {",
  "    const auth = this.accessToken ? \"Bearer \" + this.accessToken : this.apiKey ? \"Bearer \" + this.apiKey : null",
  "    const fetchImpl = this.opts.fetchImpl || fetch",
  "    return fetchImpl(this.opts.baseUrl.replace(/\\/$/, \"\") + urlPath, {",
  "      method,",
  "      headers: {",
  "        ...(body != null ? { \"content-type\": \"application/json\" } : {}),",
  "        ...(auth ? { authorization: auth } : {}),",
  "        ...headers,",
  "      },",
  "      ...(body != null ? { body: JSON.stringify(body) } : {}),",
  "    })",
  "  }",
  "",
  "  private async list(urlPath: string, params: Record<string, unknown>, ifNoneMatch?: string): Promise<{ res: Response; json: any }> {",
  "    const qs = new URLSearchParams()",
  "    for (const [k, v] of Object.entries(params)) {",
  "      if (v == null || v === \"\") continue",
  "      qs.set(k, String(v))",
  "    }",
  "    const search = qs.toString()",
  "    const res = await this.raw(\"GET\", urlPath + (search ? \"?\" + search : \"\"), undefined, ifNoneMatch ? { \"if-none-match\": ifNoneMatch } : {})",
  "    if (res.status === 304) return { res, json: null }",
  "    return { res, json: await res.json() }",
  "  }",
  "",
  "  private async err(res: Response): Promise<Error & { code?: string; status?: number }> {",
  "    let json: any = null",
  "    try { json = await res.json() } catch { /* non-JSON error body */ }",
  "    return Object.assign(new Error(json?.error || res.statusText || \"API error\"), { code: json?.code, status: res.status })",
  "  }",
  "",
].join("\n")

const methodBlocks: string[] = []
const extraBlocks: string[] = []

for (const [urlPath, ops] of Object.entries(spec.paths)) {
  for (const [method, op] of Object.entries(ops)) {
    if (!(method === "get" || method === "post" || method === "delete") || !op?.operationId) continue
    const fn = op.operationId
    const params = paramNames(op.parameters)

    if (method === "get" && urlPath.includes("{id}")) {
      const base = JSON.stringify(urlPath.replace("{id}", ""))
      methodBlocks.push([
        jsDoc(op),
        `  async ${fn}(id: string): Promise<any> {`,
        `    const res = await this.raw("GET", ${base} + encodeURIComponent(id))`,
        `    if (!res.ok) throw await this.err(res)`,
        `    const json = await res.json()`,
        `    return json.data`,
        `  }`,
      ].join("\n"))
      continue
    }

    if (method === "delete" && urlPath.includes("{id}")) {
      const base = JSON.stringify(urlPath.replace("{id}", ""))
      methodBlocks.push([
        jsDoc(op),
        `  async ${fn}(id: string): Promise<any> {`,
        `    const res = await this.raw("DELETE", ${base} + encodeURIComponent(id))`,
        `    if (!res.ok) throw await this.err(res)`,
        `    const json = await res.json()`,
        `    return json.data`,
        `  }`,
      ].join("\n"))
      continue
    }

    if (method === "get") {
      const paramLines = params.map((p) => `    ${p}?: ${p === "pageSize" || p === "page" ? "number" : "string"} | null`).join("\n")
      methodBlocks.push([
        jsDoc(op, ["Returns page data, meta and the response ETag (pass it back via opts.ifNoneMatch for 304s)."]),
        `  async ${fn}(params: {`,
        paramLines,
        `  } & { ifNoneMatch?: string } = {}): Promise<PageResult<any>> {`,
        `    const { ifNoneMatch, ...rest } = params as Record<string, unknown>`,
        `    const { res, json } = await this.list(${JSON.stringify(urlPath)}, rest, ifNoneMatch as string | undefined)`,
        `    if (res.status === 304) return { ok: true, data: [], meta: {} as any, etag: res.headers.get("etag"), notModified: true }`,
        `    if (!res.ok) throw await this.err(res)`,
        `    return { ok: true, data: json.data, meta: json.meta || {}, etag: res.headers.get("etag"), notModified: false }`,
        `  }`,
      ].join("\n"))

      if (fn === "listEmployees") {
        extraBlocks.push([
          `  /** Delta-sync helper: follows meta.nextCursor until hasMore is false.`,
          `   *  With updatedSince, moves only rows changed since the last sync. */`,
          `  async listAllEmployees(opts: { updatedSince?: string; pageSize?: number; maxPages?: number } = {}): Promise<any[]> {`,
          `    const all: any[] = []`,
          `    let cursor: string | null = null`,
          `    const maxPages = opts.maxPages ?? 500`,
          `    for (let i = 0; i < maxPages; i++) {`,
          `      const page = await this.listEmployees({ ...(opts.pageSize ? { pageSize: opts.pageSize } : {}), cursor, ...(opts.updatedSince ? { updatedSince: opts.updatedSince } : {}) })`,
          `      all.push(...page.data)`,
          `      if (!page.meta.hasMore || !page.meta.nextCursor) return all`,
          `      cursor = page.meta.nextCursor as string`,
          `    }`,
          `    throw new Error("listAllEmployees: exceeded maxPages — aborting to avoid an unbounded walk")`,
          `  }`,
        ].join("\n"))
      }
      continue
    }

    // POST endpoints (the token endpoint is specialized in the header — skip it)
    if (fn === "issueToken") continue
    methodBlocks.push([
      jsDoc(op),
      `  async ${fn}(body: Record<string, unknown>): Promise<any> {`,
      `    const res = await this.raw("POST", ${JSON.stringify(urlPath)}, body)`,
      `    if (!res.ok) throw await this.err(res)`,
      `    const json = await res.json()`,
      `    return json.data`,
      `  }`,
    ].join("\n"))
  }
}

const out = [HEADER, "", methodBlocks.join("\n\n"), "", extraBlocks.join("\n"), "}", ""].join("\n")

const dest = path.resolve(import.meta.dir, "../src/api-client/index.ts")
fs.writeFileSync(dest, out)
console.log(`generated ${dest} (${out.length} bytes)`)
